            transformed == TELEMETRY_OK ? status_name(output.status) : NULL;
        if (parsed != TELEMETRY_OK || transformed != TELEMETRY_OK || name == NULL) {
            fprintf(stderr, "invalid fields or ranges on line %zu\n", line_number);
            return 1;
